const body = $input.first().json;
const d = body.data || body;

const maxCurrent = Math.max(
  d.current_a?.l1 || 0,
  d.current_a?.l2 || 0,
  d.current_a?.l3 || 0
);

const prompt = `คุณเป็น AI ผู้เชี่ยวชาญด้านการจัดการพลังงานในโรงงานอุตสาหกรรม
วิเคราะห์ข้อมูล telemetry ของเครื่องจักรและตัดสินใจว่าควรลดกำลังการทำงานหรือไม่

ข้อมูลเครื่องจักร:
- Machine ID: ${d.machine_id}
- Timestamp: ${d.ts}
- Active Power: ${d.active_power_kw} kW
- Apparent Power: ${d.apparent_power_kva} kVA
- Power Factor: ${d.power_factor}
- Load: ${d.load_pct}%
- Max Current: ${maxCurrent.toFixed(2)} A  (L1:${d.current_a?.l1} / L2:${d.current_a?.l2} / L3:${d.current_a?.l3})
- Voltage (L1/L2/L3): ${d.voltage_v?.l1}/${d.voltage_v?.l2}/${d.voltage_v?.l3} V
- Frequency: ${d.frequency_hz} Hz
- Motor RPM: ${d.motor_rpm}
- Overcurrent Alarm: ${d.alarm_overcurrent}
- Current Mode: ${d.power_mode || 'NORMAL'}

เกณฑ์การตัดสินใจ:
1. reduce_power = true  ถ้า: active_power_kw > 8.0 หรือ load_pct > 80 หรือ alarm_overcurrent = true หรือ power_factor < 0.88
2. reduce_power = false ถ้า: ทุกค่าอยู่ในช่วงปกติ
3. risk_level: "high" ถ้า overcurrent alarm หรือ power > 10 kW | "medium" ถ้า load > 70% หรือ pf < 0.90 | "low" อื่นๆ

ตอบกลับเป็น JSON ที่ valid เท่านั้น ห้ามมี markdown หรือคำอธิบาย:
{"reduce_power": boolean, "reason": "สาเหตุสั้นๆ", "recommendation": "คำแนะนำ", "risk_level": "low|medium|high"}`;

return [{ json: { prompt, original_data: body } }];

const llmOutput = $input.first().json;
const originalData = $('Format Energy Prompt').first().json.original_data;
const d = originalData.data || originalData;

let decision = {
  reduce_power: false,
  reason: 'ไม่สามารถวิเคราะห์ได้',
  recommendation: 'ตรวจสอบด้วยตนเอง',
  risk_level: 'low'
};

try {
  const rawText = llmOutput.text || '';
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    decision = {
      reduce_power: parsed.reduce_power === true,
      reason: parsed.reason || '-',
      recommendation: parsed.recommendation || '-',
      risk_level: (parsed.risk_level || 'low').toLowerCase()
    };
  }
} catch (e) {
  decision.reason = 'Parse error: ' + e.message;
}

return [{
  json: {
    ...decision,
    machine_id: d.machine_id || 'MC-01',
    ts: d.ts || new Date().toISOString(),
    active_power_kw: d.active_power_kw,
    load_pct: d.load_pct,
    power_factor: d.power_factor,
    source: 'n8n-gemini-ai'
  }
}];
